//! The tonic server traits of the services the engine serves, generated by
//! `proto/regenerate.sh` into `src/proto/`. Every message type they name is gcloud-sdk's, the
//! type the `bigquery` client sends.

/// `google.cloud.bigquery.v2`: `JobService`, `TableService`, `DatasetService` and
/// `RowAccessPolicyService`. `model_service_server` comes with the import closure and is never
/// registered.
pub(crate) mod bigquery_v2 {
    include!("proto/google.cloud.bigquery.v2.rs");
}

/// `google.cloud.bigquery.storage.v1`: `BigQueryRead` and `BigQueryWrite`.
pub(crate) mod storage_v1 {
    include!("proto/google.cloud.bigquery.storage.v1.rs");
}
